#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <errno.h>

#define MAX_MSG_SIZE 4096
#define HEADER_SIZE 8

typedef struct {
    uint16_t version;
    uint16_t msg_type;
    int32_t  payload_length;  // signed: from network protocol
} __attribute__((packed)) msg_header_t;

typedef struct {
    char buffer[MAX_MSG_SIZE];
    size_t used;
} msg_buffer_t;

// Validates that the total message fits within our buffer constraints
// Returns 1 if valid, 0 if invalid
static int validate_message_bounds(size_t payload_len, size_t buffer_capacity) {
    size_t total_needed = HEADER_SIZE + payload_len;
    // Check for overflow in addition
    if (total_needed < payload_len) {
        return 0;
    }
    // Check that total message fits in buffer
    if (total_needed > buffer_capacity) {
        return 0;
    }
    return 1;
}

// Sanitize payload: remove any null bytes, ensure printable ASCII
static size_t sanitize_payload(const char *src, char *dst, size_t len) {
    size_t j = 0;
    for (size_t i = 0; i < len; i++) {
        if (src[i] >= 0x20 && src[i] <= 0x7e) {
            dst[j++] = src[i];
        }
    }
    dst[j] = '\0';
    return j;
}

// Process a single message from the wire format
static int process_message(const char *raw_data, size_t raw_len, msg_buffer_t *out) {
    if (raw_len < HEADER_SIZE) {
        fprintf(stderr, "Message too short for header\n");
        return -1;
    }

    msg_header_t header;
    memcpy(&header, raw_data, HEADER_SIZE);

    // Version check
    if (header.version != 1) {
        fprintf(stderr, "Unsupported protocol version: %u\n", header.version);
        return -1;
    }

    // Validate message type
    if (header.msg_type > 5) {
        fprintf(stderr, "Unknown message type: %u\n", header.msg_type);
        return -1;
    }

    int32_t payload_len_signed = header.payload_length;

    // Reject negative and zero lengths
    if (payload_len_signed <= 0) {
        fprintf(stderr, "Invalid payload length: %d\n", payload_len_signed);
        return -1;
    }

    size_t payload_len = (size_t)payload_len_signed;

    // Validate bounds - ensure message fits in output buffer
    if (!validate_message_bounds(payload_len, MAX_MSG_SIZE)) {
        fprintf(stderr, "Message exceeds buffer capacity\n");
        return -1;
    }

    // Verify we have enough raw data
    if (raw_len < HEADER_SIZE + payload_len) {
        fprintf(stderr, "Truncated message\n");
        return -1;
    }

    // Copy and sanitize payload into output buffer
    const char *payload_start = raw_data + HEADER_SIZE;
    out->used = sanitize_payload(payload_start, out->buffer, payload_len);

    return 0;
}

// Handle incoming connection
static void handle_connection(int client_fd) {
    char recv_buf[8192];
    msg_buffer_t output;
    memset(&output, 0, sizeof(output));

    ssize_t bytes = recv(client_fd, recv_buf, sizeof(recv_buf), 0);
    if (bytes <= 0) {
        return;
    }

    if (process_message(recv_buf, (size_t)bytes, &output) == 0) {
        // Echo back sanitized payload
        send(client_fd, output.buffer, output.used, 0);
    }
}

int main(int argc, char *argv[]) {
    int port = 9090;
    if (argc > 1) port = atoi(argv[1]);

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) { perror("socket"); return 1; }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind"); close(server_fd); return 1;
    }

    if (listen(server_fd, 5) < 0) {
        perror("listen"); close(server_fd); return 1;
    }

    printf("Listening on port %d\n", port);

    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;
        handle_connection(client_fd);
        close(client_fd);
    }

    return 0;
}
